// Legacy public Credits and bylines with stored join phrases.
const phraseIds = {
    album: '64b0000000000000000000a1',
    track: '64b0000000000000000000a2',
    alpha: '64b0000000000000000000b1',
    beta: '64b0000000000000000000b2',
    gamma: '64b0000000000000000000b3',
    hidden: '64b0000000000000000000b4',
    delta: '64b0000000000000000000b5',
    label: '64b0000000000000000000c1'
};
const phraseSubjects = [
    { _id: phraseIds.alpha, name: 'Alpha', collection: 'artists' },
    { _id: phraseIds.beta, name: 'Beta', collection: 'artists' },
    { _id: phraseIds.gamma, name: 'Gamma', collection: 'artists' },
    { _id: phraseIds.delta, name: 'Delta', collection: 'artists' },
    { _id: phraseIds.label, name: 'Lorem Records', collection: 'organizations' }
];
// Alpha's phrase joins the adjacent Beta; Beta's invalid phrase falls back to `, `; Gamma's
// phrase is dropped because the hidden Credit separates it from Delta; the label stays out.
const phraseCredits = () => [
    { creditId: 'phrase_alpha', subjectType: 'artist', subjectId: phraseIds.alpha, role: 'primary', order: 0, joinPhrase: ' & ', musicBrainzId: 'synthetic' },
    { creditId: 'phrase_beta', subjectType: 'artist', subjectId: phraseIds.beta, role: 'primary', order: 1, joinPhrase: 'x\u200By' },
    { creditId: 'phrase_gamma', subjectType: 'artist', subjectId: phraseIds.gamma, role: 'featured', order: 2, joinPhrase: ' / ' },
    { creditId: 'phrase_hidden', subjectType: 'artist', subjectId: phraseIds.hidden, role: 'primary', order: 3, joinPhrase: ' & ' },
    { creditId: 'phrase_delta', subjectType: 'artist', subjectId: phraseIds.delta, role: 'performer', order: 4, createdBy: 'private-owner' },
    { creditId: 'phrase_label', subjectType: 'organization', subjectId: phraseIds.label, role: 'label', order: 5, joinPhrase: ' / ' }
];
const phraseAlbum = () => ({
    _id: phraseIds.album, title: 'Phrase Album', audioTrackIds: [], lifecycleStatus: 'ready',
    attributionStatus: 'documented', credits: phraseCredits()
});
const phraseTrack = () => ({
    _id: phraseIds.track, title: 'Phrase Track', uploadStatus: 'ready', s3Key: phraseIds.track,
    artistIds: [], attributionStatus: 'documented', credits: phraseCredits()
});
const phraseSubjectNames = new Map(phraseSubjects.map((subject) =>
    [`${subject.collection === 'artists' ? 'artist' : 'organization'}:${subject._id}`, subject.name]));
const expectedPhraseByline = 'Alpha & Beta, Gamma, Delta';

/** Sets environment values for one test and restores the previous values afterwards. */
const withEnvironment = (t: TestContext, values: Record<string, string>) => {
    const previous = Object.fromEntries(Object.keys(values).map((key) => [key, process.env[key]]));
    Object.assign(process.env, values);
    t.after(() => {
        for (const [key, value] of Object.entries(previous)) {
            if (value === undefined) delete process.env[key];
            else process.env[key] = value;
        }
    });
};

test('legacy public Credits expose only the five declared fields and phrase-aware bylines', (t) => {
    withEnvironment(t, { CATALOG_CREDIT_READS_ENABLED: 'true' });
    const album = toPublicAlbum(phraseAlbum(), [], phraseSubjectNames);
    const track = toPublicAudioTrack(phraseTrack(), undefined, undefined, phraseSubjectNames);
    assert.ok(track);
    for (const dto of [album, track]) {
        assert.equal(dto.displayByline, expectedPhraseByline);
        assert.equal(dto.attributionStatus, 'documented');
        assert.deepEqual(dto.credits?.map((credit) => Object.keys(credit).sort()),
            Array.from({ length: 5 }, () => ['name', 'order', 'role', 'subjectId', 'subjectType']));
        assert.deepEqual(dto.credits?.map((credit) => [credit.name, credit.role, credit.order]), [
            ['Alpha', 'primary', 0], ['Beta', 'primary', 1], ['Gamma', 'featured', 2],
            ['Delta', 'performer', 4], ['Lorem Records', 'label', 5]
        ]);
        assertNoInternalFields(dto);
    }
});

test('legacy public DTOs omit the byline when no credited subject is visible', (t) => {
    withEnvironment(t, { CATALOG_CREDIT_READS_ENABLED: 'true' });
    // No subject name resolves, as when every credited Artist and Organization is hidden.
    const album = toPublicAlbum(phraseAlbum(), [], new Map());
    const track = toPublicAudioTrack(phraseTrack(), undefined, undefined, new Map());
    assert.ok(track);
    for (const dto of [album, track]) {
        assert.equal(Object.prototype.hasOwnProperty.call(dto, 'displayByline'), false);
        assert.deepEqual(dto.credits, []);
        assert.equal(dto.attributionStatus, 'documented');
    }
});

test('the Library byline resolver returns the same phrase-aware byline', async (t) => {
    withEnvironment(t, {
        DB_CONN_STRING: 'mongodb://127.0.0.1:1',
        DB_NAME: 'synthetic',
        CATALOG_CREDIT_READS_ENABLED: 'true'
    });
    // A read-only stand-in returning each subject collection whole; the hidden Artist is absent.
    const db = {
        command: async () => ({ isWritablePrimary: true, setName: 'synthetic', logicalSessionTimeoutMinutes: 30, maxWireVersion: 25 }),
        collection: (name: string) => ({
            listIndexes: () => ({
                toArray: async () => databaseIndexes.filter((index) => index.collection === name)
                    .map((index) => ({ key: index.keys, ...structuredClone(index.options ?? {}) }))
            }),
            find: () => {
                const chain = {
                    project: () => chain,
                    toArray: async () => phraseSubjects.filter((subject) => subject.collection === name)
                        .map((subject) => ({ _id: new ObjectId(subject._id), name: subject.name }))
                };
                return chain;
            }
        })
    } as unknown as Db;
    t.mock.method(MongoClient.prototype, 'connect', async function (this: MongoClient) { return this; });
    t.mock.method(MongoClient.prototype, 'db', () => db);
    t.mock.method(MongoClient.prototype, 'close', async () => undefined);
    await connectToDatabase({ initializeIndexes: false, logReady: false });
    try {
        const bylines = await resolvePublicCatalogBylines([phraseAlbum(), phraseTrack()]);
        assert.deepEqual([...bylines], [[phraseIds.album, expectedPhraseByline], [phraseIds.track, expectedPhraseByline]]);
    } finally {
        await disconnectFromDatabase();
    }
});

test('the Credit read rollback still omits every legacy public Credit field', (t) => {
    withEnvironment(t, { CATALOG_CREDIT_READS_ENABLED: 'false' });
    const album = toPublicAlbum(phraseAlbum(), [], phraseSubjectNames);
    const track = toPublicAudioTrack(phraseTrack(), undefined, undefined, phraseSubjectNames);
    for (const dto of [album, track]) {
        for (const key of ['credits', 'displayByline', 'attributionStatus']) {
            assert.equal(Object.prototype.hasOwnProperty.call(dto, key), false, key);
        }
    }
});
